-- Migration to enforce customer_id NOT NULL and add validated foreign key
-- Step 1: Add a CHECK constraint for NOT NULL (not validated initially)
ALTER TABLE orders ADD CONSTRAINT orders_customer_id_not_null CHECK (customer_id IS NOT NULL) NOT VALID;

-- Step 2: Validate the CHECK constraint (scans table, does not block writes)
ALTER TABLE orders VALIDATE CONSTRAINT orders_customer_id_not_null;

-- Step 3: Add foreign key constraint NOT VALID
ALTER TABLE orders ADD CONSTRAINT orders_customer_id_fkey FOREIGN KEY (customer_id) REFERENCES customers(id) NOT VALID;

-- Step 4: Validate the foreign key (scans table, does not block writes)
ALTER TABLE orders VALIDATE CONSTRAINT orders_customer_id_fkey;

-- Step 5: Set column to NOT NULL (requires brief ACCESS EXCLUSIVE lock)
-- Use a loop with NOWAIT to avoid blocking app transactions for more than 500ms
DO $$
DECLARE
    acquired boolean := false;
    attempts int := 5000;  -- up to ~50 seconds of retries
BEGIN
    FOR i IN 1..attempts LOOP
        BEGIN
            LOCK TABLE orders IN ACCESS EXCLUSIVE MODE NOWAIT;
            acquired := true;
            EXIT;
        EXCEPTION WHEN lock_not_available THEN
            PERFORM pg_sleep(0.01);  -- 10 ms
        END;
    END LOOP;
    IF NOT acquired THEN
        RAISE EXCEPTION 'Failed to acquire ACCESS EXCLUSIVE lock on orders after % attempts', attempts;
    END IF;
    ALTER TABLE orders ALTER COLUMN customer_id SET NOT NULL;
END $$;

